const returnSandboxSessionResume = `-- name: ReturnSandboxSessionResume :execrows
UPDATE sandbox_sessions SET state='paused',
  resume_requested_at=CASE WHEN $1::boolean THEN coalesce(resume_requested_at, now()) ELSE NULL END,
  resume_not_before=CASE WHEN $1::boolean THEN now()+make_interval(secs=>$2::double precision) END,
  lease_token=NULL, lease_owner=NULL, lease_expires_at=NULL, updated_at=now()
 WHERE id=$3::text::uuid AND lease_token=$4::text AND state='resuming'
`

type ReturnSandboxSessionResumeParams struct {
	Retry        bool
	RetrySeconds float64
	SessionID    string
	LeaseToken   string
}

// A resume that never booted goes back to paused with its capture. retry
// keeps the request, so a claim tries again after retry_seconds; a refused
// resume drops it until apid asks again.
func (q *Queries) ReturnSandboxSessionResume(ctx context.Context, db DBTX, arg ReturnSandboxSessionResumeParams) (int64, error) {
	result, err := db.Exec(ctx, returnSandboxSessionResume,
		arg.Retry,
		arg.RetrySeconds,
		arg.SessionID,
		arg.LeaseToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revokeAgentCallbacks = `-- name: RevokeAgentCallbacks :one
INSERT INTO agent_callback_revocations (endpoint_id, thread_id, account_id, revoked_at)
VALUES ($1::text::uuid, $2::text, $3::text::uuid, clock_timestamp())
ON CONFLICT (endpoint_id, thread_id) DO UPDATE SET revoked_at = clock_timestamp(), account_id = excluded.account_id
RETURNING revoked_at
`

type RevokeAgentCallbacksParams struct {
	EndpointID string
	ThreadID   string
	AccountID  string
}

// ADR-20261030125501 §3: revoke every callback URL of a thread issued until now.
func (q *Queries) RevokeAgentCallbacks(ctx context.Context, db DBTX, arg RevokeAgentCallbacksParams) (pgtype.Timestamptz, error) {
	row := db.QueryRow(ctx, revokeAgentCallbacks, arg.EndpointID, arg.ThreadID, arg.AccountID)
	var revoked_at pgtype.Timestamptz
	err := row.Scan(&revoked_at)
	return revoked_at, err
}

