const setSandboxSessionFrozen = `-- name: SetSandboxSessionFrozen :execrows
UPDATE sandbox_sessions SET state=CASE WHEN state='pausing' THEN 'pausing'
    WHEN $1::boolean THEN 'frozen' ELSE 'ready' END, updated_at=now()
 WHERE id=$2::text::uuid AND lease_token=$3::text AND state IN ('ready','frozen','pausing')
`

type SetSandboxSessionFrozenParams struct {
	Frozen     bool
	SessionID  string
	LeaseToken string
}

// A pause thaws a frozen VM before it captures it; the session stays
// pausing (ADR-20261122132055 §2).
func (q *Queries) SetSandboxSessionFrozen(ctx context.Context, db DBTX, arg SetSandboxSessionFrozenParams) (int64, error) {
	result, err := db.Exec(ctx, setSandboxSessionFrozen, arg.Frozen, arg.SessionID, arg.LeaseToken)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settleCapturedEmailDeliveries = `-- name: SettleCapturedEmailDeliveries :many
UPDATE agent_deliveries d SET state=CASE WHEN o.disposition='queued' THEN 'delivered' ELSE 'failed' END,
  outcome_code=CASE WHEN o.disposition='queued' THEN NULL ELSE 'mail_'||o.disposition END,
  outcome_message=CASE WHEN o.disposition='queued' THEN NULL WHEN o.disposition='unavailable'
    THEN 'the account has no address that receives mail' ELSE 'the mail outbox did not queue the summary' END,
  finished_at=now(), updated_at=now()
 FROM platform_mail_agent_run_observations o
 WHERE o.delivery_id=d.id AND d.destination='email' AND d.state='pending'
 RETURNING d.run_id::text AS run_id,d.destination,d.state
`

type SettleCapturedEmailDeliveriesRow struct {
	RunID       string
	Destination string
	State       string
}

// An email delivery ends with apid's mail outbox receipt: queued is
// delivered, any other disposition fails. agentd only reads the receipt.
func (q *Queries) SettleCapturedEmailDeliveries(ctx context.Context, db DBTX) ([]SettleCapturedEmailDeliveriesRow, error) {
	rows, err := db.Query(ctx, settleCapturedEmailDeliveries)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SettleCapturedEmailDeliveriesRow{}
	for rows.Next() {
		var i SettleCapturedEmailDeliveriesRow
		if err := rows.Scan(&i.RunID, &i.Destination, &i.State); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

